Looking at the working file and the parent document, I need to update the Puppeteer server to:

1. Always keep running (handle disconnections gracefully)
2. Log when new connections start and end
3. Monitor CDP connections

```js browser/pupeteer.js
const puppeteer = require('puppeteer-core');

const CDP_PORT = 92222;
const CHROME_PATH = process.env.CHROME_PATH || '/usr/bin/chromium';

let browser = null;

async function launchBrowser() {
  console.log(`[vibe] Launching Chrome with CDP port ${CDP_PORT}...`);

  browser = await puppeteer.launch({
    executablePath: CHROME_PATH,
    headless: false,           // headed — visible on Debian desktop / VNC
    args: [
      `--remote-debugging-port=${CDP_PORT}`,
      '--remote-debugging-address=0.0.0.0',   // allow external connections
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--window-size=1280,900',
    ],
    defaultViewport: null,     // use full window size
  });

  console.log(`[vibe] Chrome launched. CDP available at http://0.0.0.0:${CDP_PORT}`);

  browser.on('disconnected', () => {
    console.log('[vibe] Browser disconnected — restarting in 2s...');
    browser = null;
    setTimeout(launchBrowser, 2000);
  });

  browser.on('targetcreated', async (target) => {
    const url = target.url();
    const type = target.type();
    console.log(`[vibe] [connection] New target created — type: ${type} | url: ${url}`);
  });

  browser.on('targetdestroyed', async (target) => {
    const url = target.url();
    const type = target.type();
    console.log(`[vibe] [connection] Target destroyed   — type: ${type} | url: ${url}`);
  });

  browser.on('targetchanged', async (target) => {
    const url = target.url();
    const type = target.type();
    console.log(`[vibe] [connection] Target navigated   — type: ${type} | url: ${url}`);
  });

  return browser;
}

// ── CDP connection polling — log active client count ──────────────────────────
const http = require('http');

function pollCDPClients() {
  const req = http.get(`http://localhost:${CDP_PORT}/json/version`, (res) => {
    // version endpoint responding = browser alive
  });
  req.on('error', () => {
    // browser not yet up — ignore
  });
  req.end();
}

// Poll every 10 seconds just to confirm browser is still reachable
setInterval(pollCDPClients, 10_000);

// ── Graceful shutdown ──────────────────────────────────────────────────────────
async function shutdown(signal) {
  console.log(`[vibe] ${signal} received — closing browser`);
  if (browser) {
    try {
      await browser.close();
    } catch (err) {
      console.error('[vibe] Error closing browser:', err.message);
    }
  }
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ── Unhandled rejections — log but keep process alive ─────────────────────────
process.on('unhandledRejection', (reason) => {
  console.error('[vibe] Unhandled rejection (keeping server alive):', reason);
});

process.on('uncaughtException', (err) => {
  console.error('[vibe] Uncaught exception (keeping server alive):', err.message);
});

// ── Start ──────────────────────────────────────────────────────────────────────
(async () => {
  await launchBrowser();
  console.log('[vibe] Server is running. Waiting for CDP connections...');
})();
```

### Key changes:

| Change | Details |
|--------|---------|
| **Always running** | `browser.on('disconnected')` triggers an automatic restart after 2s — server never exits |
| **Connection logging** | `targetcreated` / `targetdestroyed` / `targetchanged` events log every CDP tab/page open and close with type + URL |
| **Unhandled errors** | `unhandledRejection` + `uncaughtException` handlers log errors but keep the process alive |
| **SIGINT added** | Catches `Ctrl+C` in addition to `SIGTERM` for clean dev shutdowns |
| **CDP health poll** | Pings `/json/version` every 10s to confirm browser is reachable (silent — only errors surface) |
| **Browser ref guarded** | `browser = null` on disconnect prevents stale reference during restart window |
